ROOT=Path(__file__).resolve().parent

def slug(s):
    table={'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e','ж':'zh','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'h','ц':'c','ч':'ch','ш':'sh','щ':'sch','ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya'}
    x=''.join(table.get(c,c) for c in s.lower())
    x=re.sub(r'[^a-z0-9]+','_',x).strip('_')
    return x

offers=[]
def add(cat,name,reward,hold,condition, *, code=None, title=None, age_min=18,age_max=120, emoji=None, source='', url='', minimum=0, kind='', note=''):
    code=code or slug(name)
    offers.append(dict(category=cat, slug=code, name=name, title=title or name, code=code, emoji=emoji or {'cards':'💳','bk':'⚽','mfo':'🏦','cpl':'📝'}[cat], reward=int(reward), hold=int(hold), condition=condition, age_min=int(age_min), age_max=int(age_max), minimum=int(minimum), kind=kind, source_url=source, url=url, note=note))

